# t81 — visual v2: modo noturno (tokens), palco da orbe no topo da Visão, grade de indicadores, cockpit da ficha e funil de Oportunidades
import sys, time, re; sys.path.insert(0, '/home/claude/test')
from t40_lib import *
em = 'qa.t81.%d@totvs.com.br' % time.time()
A, errs = open_h(em)
A.set_viewport_size({'width': 1440, 'height': 900})
A.evaluate("UI.view='importar'; render()"); A.wait_for_timeout(300)
A.set_input_files('#f-cart', D + 'carteira.xlsx'); A.wait_for_timeout(500); A.click('[data-a=impPrev]'); A.wait_for_timeout(300); A.click('[data-a=impGo]'); A.wait_for_timeout(3000)
lum = "(s=>{const m=s.match(/[\\d.]+/g).map(Number).slice(0,3).map(v=>{v/=255;return v<=.03928?v/12.92:Math.pow((v+.055)/1.055,2.4)});return .2126*m[0]+.7152*m[1]+.0722*m[2]})"
# tema
ck('padrão: tema claro', ev(A, "!document.documentElement.dataset.theme && themeGet()==='light'"))
ev(A, "UI.view='geral';render();0"); A.wait_for_timeout(1200)
ck('botão de tema na barra superior', ev(A, "!!document.querySelector('#top #th-btn')"))
A.click('#th-btn'); A.wait_for_timeout(300)
ck('clique ativa o modo noturno e persiste', ev(A, "document.documentElement.dataset.theme==='dark' && localStorage.getItem('rf.theme')==='dark'"))
ck('noturno: fundo escuro e texto claro', ev(A, "(()=>{const L=%s;const b=L(getComputedStyle(document.body).backgroundColor),c=document.querySelector('#app .card'),cb=L(getComputedStyle(c).backgroundColor),ct=L(getComputedStyle(c).color);return b<.05&&cb<.08&&ct>.6})()" % lum))
low = ev(A, """(()=>{const L=%s;const bg=e=>{for(;e;e=e.parentElement){const c=getComputedStyle(e).backgroundColor;if(c&&!/rgba\\(.*, 0\\)|transparent/.test(c))return c}return 'rgb(0,19,28)'};const out=[];document.querySelectorAll('#app .card h3,#app .card p,#app .kpi .v,#app .kpi .l,#app .ck a,#app .ck span,#app .ck b').forEach(e=>{if(!e.offsetParent||!e.textContent.trim()||e.closest('.rf3d'))return;const a=L(getComputedStyle(e).color),b=L(bg(e)),r=(Math.max(a,b)+.05)/(Math.min(a,b)+.05);if(r<4.5)out.push(e.className+':'+e.textContent.trim().slice(0,24)+' '+r.toFixed(2))});return out.slice(0,8)})()""" % lum)
ck('noturno: contraste de texto ≥ 4,5:1 na Visão', not low, low)
# Visão v2
ck('palco da orbe abre a Visão (antes dos KPIs e dos primeiros passos)', ev(A, "(()=>{const a=document.querySelector('#app'),k=[...a.children].filter(e=>!e.matches('.alert'));return k[0]&&k[0].id==='rf3d'&&k[1]&&k[1].id==='ck'})()"))
ck('palco mostra o MRR informado em destaque', 'R$ 49.000,50' in ev(A, "document.querySelector('.rf3d-t').textContent").replace('\xa0', ' '))
ck('controles da orbe mantidos (Orbe/Barras e 3D)', ev(A, "!!document.querySelector('[data-r3=orb]')&&!!document.querySelector('[data-r3=bars]')&&!!document.querySelector('[data-r3=fx]')"))
ck('painel "Onde vale aprofundar hoje" no palco', ev(A, "!!document.querySelector('.rf3d .ck-hoje [data-a=openTab]')"))
g = ev(A, "({bars:document.querySelectorAll('.ck-c:first-child .ck-bars li').length,sols:document.querySelectorAll('.ck-c:nth-child(2) .ck-bars li').length,big:document.querySelector('.ck-big b').textContent,rings:document.querySelectorAll('.ck-rings .ck-ring').length,cells:document.querySelectorAll('.ck-map button.ck-cell').length,ok:document.querySelectorAll('.ck-map button.ck-cell.ok').length,sb:(document.querySelector('.sb-item[data-v=pend] .badge')||{}).textContent,pend:(document.querySelector('.ck-pend b')||{}).textContent})")
print(g)
ck('MRR por cliente: 4 barras (dados da planilha)', g['bars'] == 4)
ck('soluções TOTVS mais sugeridas: até 5, por nº de clientes', 1 <= g['sols'] <= 5)
ck('oportunidades mapeadas = 12; mapa com 12 células (1 identificada)', g['big'] == '12' and g['cells'] == 12 and g['ok'] == 1)
ck('pendências = contagem do menu lateral', g['pend'] == g['sb'])
ck('KPIs originais preservados', ev(A, "document.querySelectorAll('#app .grid.g4 .kpi').length") >= 4)
A.locator('.ck-map button.ck-cell.ok').click(); A.wait_for_timeout(700)
ck('célula do mapa abre o raio-X do cliente', ev(A, "UI.view==='cliente'&&UI.ctab==='raiox'"))
# ficha
ck('ficha: cabeçalho-cockpit com ações originais dentro', ev(A, "(()=>{const b=document.querySelector('#app .ck-ch');return !!b&&['pesqCli','expCli','briefOpen'].every(a=>b.querySelector('[data-a='+a+']'))})()"))
ck('ficha: MRR e participação na carteira', ev(A, "/15\\.000,00/.test(document.querySelector('.ck-st').textContent)&&/30,6% da carteira/.test(document.querySelector('.ck-st').textContent)"))
ck('ficha: trilha de prontidão 1/4 com atalhos', ev(A, "document.querySelectorAll('.ck-rd li').length===4&&document.querySelectorAll('.ck-rd li.ok').length===1&&document.querySelectorAll('.ck-rd a[data-a=ctab]').length===3"))
A.locator('.ck-rd a[data-v=fichas]').click(); A.wait_for_timeout(500)
ck('atalho "Anexar ficha" abre a aba Fichas', ev(A, "UI.ctab") == 'fichas')
ck('faixa de status original preservada', ev(A, "document.querySelectorAll('#app .strip .sti').length") == 7)
# oportunidades
ev(A, "UI.view='oport';render();0"); A.wait_for_timeout(900)
ck('oportunidades: funil com 4 números', ev(A, "[...document.querySelectorAll('#ckf b')].map(x=>x.textContent).join(',')") == '12,11,1,0')
A.locator('[data-ckcl=identificada]').click(); A.wait_for_timeout(600)
ck('filtro rápido "Identificadas" aplica o mesmo filtro do seletor', ev(A, "OPF().cl==='identificada'&&document.querySelectorAll('#app .card.opc').length===1&&document.querySelector('[data-c=opf][data-f=cl]').value==='identificada'"))
A.locator('[data-ckcl=\"\"]').click(); A.wait_for_timeout(500)
# configurações + papel
ev(A, "UI.view='conta';render();0"); A.wait_for_timeout(700)
ck('Configurações: cartão Aparência com 3 opções', ev(A, "document.querySelectorAll('#th-card [data-th]').length") == 3)
A.locator('#th-card [data-th=light]').click(); A.wait_for_timeout(300)
ck('voltar ao claro remove o tema', ev(A, "!document.documentElement.dataset.theme&&localStorage.getItem('rf.theme')==='light'"))
# celular: grade e cockpit ficam fora; tema continua disponível
A.set_viewport_size({'width': 390, 'height': 844}); ev(A, "UI.view='geral';render();0"); A.wait_for_timeout(900)
ck('celular: grade de indicadores e orbe ocultas, sem rolagem lateral', ev(A, "(()=>{const k=document.querySelector('#ck');return (!k||getComputedStyle(k).display==='none')&&document.documentElement.scrollWidth<=innerWidth})()"))
ev(A, "themeSet('dark')"); A.wait_for_timeout(300)
ck('celular: modo noturno aplicado', ev(A, "(()=>{const L=%s;return L(getComputedStyle(document.body).backgroundColor)<.05})()" % lum))
ck('sem erros de página', not errs, errs)
print('FAILS', F)
p.stop()
